/**
 * Repository locations used by the card content tools (04 §2.1, §2.5; 05 §8.1).
 *
 *   labs/<card-id>/                 card content (lab.yaml, manual/, checks/, quiz.yaml, assets/, stacks/)
 *   labs/_schema/                   JSON Schemas written by `labs:schema`
 *   labs/_catalog/taxonomy.yaml     hand-written taxonomy (05 §8.2)
 *   labs/_catalog/catalog.yaml      generated by `labs:catalog` (05 §8.3), committed
 *   labs/_tracks/<track-id>.yaml    learning paths (atl.track/v2, tracks-and-catalog §7.3)
 *   labs/_pricing/dimensions.yaml   pricingKey → Price List query (04 §3.4; no prices)
 *   labs/_shared/checks/*.yaml      checks shared by every card (no-world-ssh, …)
 *   dist/content/<catalogVersion>/  `labs:build` output (05 §8.4), not committed
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

/** scripts/labs/src (or dist) → repository root. */
export const REPO_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../../..');

export interface LabsPaths {
  repo: string;
  labs: string;
  schema: string;
  catalogDir: string;
  taxonomy: string;
  catalog: string;
  tracks: string;
  pricing: string;
  sharedChecks: string;
  registry: string;
  rules: string;
  experiments: string;
  checkBundleSchemas: string;
  moduleCli: string;
  platformVersion: string;
  dist: string;
}

export function labsPaths(labsDir?: string, repo: string = REPO_ROOT): LabsPaths {
  const labs = path.resolve(labsDir ?? path.join(repo, 'labs'));
  return {
    repo,
    labs,
    schema: path.join(labs, '_schema'),
    catalogDir: path.join(labs, '_catalog'),
    taxonomy: path.join(labs, '_catalog', 'taxonomy.yaml'),
    catalog: path.join(labs, '_catalog', 'catalog.yaml'),
    tracks: path.join(labs, '_tracks'),
    pricing: path.join(labs, '_pricing', 'dimensions.yaml'),
    sharedChecks: path.join(labs, '_shared', 'checks'),
    registry: path.join(repo, 'modules', 'registry.yaml'),
    rules: path.join(repo, 'backend', 'src', 'rules', 'rules.ts'),
    experiments: path.join(repo, 'experiments'),
    checkBundleSchemas: path.join(repo, 'platform', 'checks', 'src', 'args-schemas.mjs'),
    moduleCli: path.join(repo, 'scripts', 'module-cli'),
    platformVersion: path.join(repo, 'platform', 'VERSION'),
    dist: path.join(repo, 'dist'),
  };
}

export function readTextIfExists(file: string): string | null {
  try {
    return fs.readFileSync(file, 'utf8');
  } catch {
    return null;
  }
}

/** Forward slashes for paths that end up in content (manifest keys, sources). */
export function posix(p: string): string {
  return p.split(path.sep).join('/');
}
